  function metadata(){const p=projects[active],number=String(active+1).padStart(2,'0');$('.m-current').textContent=number;const ghost=$('.m-ghost-index');ghost.textContent=number;if(!reduced.matches)ghost.animate([{opacity:0,transform:'translateY(10px)'},{opacity:1,transform:'translateY(0)'}],{duration:600,easing:'cubic-bezier(.22,1,.36,1)'});root.style.setProperty('--orbit-turn',`${active*72}deg`);$('.m-project-title').textContent=p.title;$('.m-project-title').href=`work/${p.id}/index.html`;$('.m-project-tag').textContent=p.subtitle;$('.m-selected-link').href=`work/${p.id}/index.html`;stage.href=`work/${p.id}/index.html`;stage.setAttribute('aria-label',`查看${p.title}，可拖动切换作品`);dots.forEach((b,i)=>b.setAttribute('aria-pressed',String(i===active)));const box=$('.m-project-text');box.classList.remove('m-fade');void box.offsetWidth;box.classList.add('m-fade');}
