  stage.addEventListener('pointerenter',e=>{if(e.pointerType==='mouse')follower.classList.add('visible');});stage.addEventListener('pointerleave',()=>follower.classList.remove('visible'));root.addEventListener('pointerleave',()=>{pointer.x=pointer.y=0;pointerDirty=true;wake();});
  document.addEventListener('click',e=>{if(!e.target.closest('.m-versions'))$('.m-versions').open=false;});
  const gl=reduced.matches?null:canvas.getContext('webgl',{alpha:false,antialias:false,preserveDrawingBuffer:true,powerPreference:'low-power'});
  let program,uniforms,buffer;
  if(gl){try{
    const vertex='attribute vec2 a;varying vec2 uv;void main(){uv=a*.5+.5;gl_Position=vec4(a,0.,1.);}';
    const fragment=`precision highp float;varying vec2 uv;uniform sampler2D imageA;uniform sampler2D imageB;uniform float progress;uniform float direction;uniform vec2 size;uniform vec2 ratioA;uniform vec2 ratioB;uniform vec2 mouse;uniform vec2 focusA;uniform vec2 focusB;
      vec2 fitted(vec2 p,vec2 image,vec2 focus){float canvasAspect=size.x/size.y;float imageAspect=image.x/image.y;vec2 scale=canvasAspect>imageAspect?vec2(1.,imageAspect/canvasAspect):vec2(canvasAspect/imageAspect,1.);return p*scale+(1.-scale)*focus;}
      void main(){float p=progress;float energy=sin(p*3.14159265);vec2 base=uv;vec2 toMouse=(base-.5)-mouse*.35;float lens=exp(-dot(toMouse,toMouse)*7.);base+=(mouse*.012)*lens;float wave=sin(base.y*6.2+p*3.4)*.11*energy;float edge=p*1.55-.25;float curtain=smoothstep(edge-.12,edge+.12,base.x+wave);float warp=sin(base.y*3.14)*energy*.19*direction;vec2 aUv=fitted(base+vec2(warp,0.),ratioA,focusA);vec2 bUv=fitted(base-vec2(warp,0.),ratioB,focusB);float zoom=1.+energy*.09;aUv=(aUv-.5)/zoom+.5;bUv=(bUv-.5)/zoom+.5;vec3 aColor=texture2D(imageA,aUv).rgb;vec3 bColor=texture2D(imageB,bUv).rgb;vec3 color=mix(bColor,aColor,curtain);float seam=pow(1.-abs(curtain*2.-1.),3.)*energy;float fringe=energy*.003;color.r=mix(texture2D(imageB,bUv+vec2(fringe,0.)).r,texture2D(imageA,aUv+vec2(fringe,0.)).r,curtain);color.b=mix(texture2D(imageB,bUv-vec2(fringe,0.)).b,texture2D(imageA,aUv-vec2(fringe,0.)).b,curtain);color+=seam*.035;gl_FragColor=vec4(color,1.);}`;
    function shader(type,source){const s=gl.createShader(type);gl.shaderSource(s,source);gl.compileShader(s);if(!gl.getShaderParameter(s,gl.COMPILE_STATUS))throw Error('Shader compilation failed');return s;}
    program=gl.createProgram();gl.attachShader(program,shader(gl.VERTEX_SHADER,vertex));gl.attachShader(program,shader(gl.FRAGMENT_SHADER,fragment));gl.linkProgram(program);if(!gl.getProgramParameter(program,gl.LINK_STATUS))throw Error('Shader linking failed');gl.useProgram(program);buffer=gl.createBuffer();gl.bindBuffer(gl.ARRAY_BUFFER,buffer);gl.bufferData(gl.ARRAY_BUFFER,new Float32Array([-1,-1,1,-1,-1,1,1,1]),gl.STATIC_DRAW);const attribute=gl.getAttribLocation(program,'a');gl.enableVertexAttribArray(attribute);gl.vertexAttribPointer(attribute,2,gl.FLOAT,false,0,0);uniforms={};for(const name of ['imageA','imageB','progress','direction','size','ratioA','ratioB','mouse','focusA','focusB'])uniforms[name]=gl.getUniformLocation(program,name);
    for(let i=0;i<projects.length;i++){const image=new Image();const texture=gl.createTexture();gl.bindTexture(gl.TEXTURE_2D,texture);gl.texParameteri(gl.TEXTURE_2D,gl.TEXTURE_WRAP_S,gl.CLAMP_TO_EDGE);gl.texParameteri(gl.TEXTURE_2D,gl.TEXTURE_WRAP_T,gl.CLAMP_TO_EDGE);gl.texParameteri(gl.TEXTURE_2D,gl.TEXTURE_MIN_FILTER,gl.LINEAR);gl.texParameteri(gl.TEXTURE_2D,gl.TEXTURE_MAG_FILTER,gl.LINEAR);gl.texImage2D(gl.TEXTURE_2D,0,gl.RGBA,1,1,0,gl.RGBA,gl.UNSIGNED_BYTE,new Uint8Array([220,210,195,255]));textures.push({texture,width:1,height:1,ready:false});image.onload=()=>{if(contextLost)return;gl.bindTexture(gl.TEXTURE_2D,texture);gl.pixelStorei(gl.UNPACK_FLIP_Y_WEBGL,true);gl.texImage2D(gl.TEXTURE_2D,0,gl.RGBA,gl.RGBA,gl.UNSIGNED_BYTE,image);Object.assign(textures[i],{width:image.width,height:image.height,ready:true});if(i===current)stage.classList.add('webgl-ready');wake();};image.src=projects[i].coverThumb.replace(/^\//,'');}
  }catch{program=null;stage.classList.remove('webgl-ready');}}
  canvas.addEventListener('webglcontextlost',e=>{e.preventDefault();contextLost=true;stage.classList.remove('webgl-ready');});
  function resize(){if(!gl||!program||contextLost)return;const b=stage.getBoundingClientRect(),dpr=Math.min(devicePixelRatio||1,1.7);const w=Math.round(b.width*dpr),h=Math.round(b.height*dpr);if(canvas.width!==w||canvas.height!==h){canvas.width=w;canvas.height=h;gl.viewport(0,0,w,h);}wake();}
  const resizeObserver=new ResizeObserver(resize);resizeObserver.observe(stage);
